import 'package:material_ui/material_ui.dart';

import 'gen/app_localizations.dart';

/// The localizations the app is built with: its own strings, then Material,
/// Widgets and Cupertino from `material_ui` and `cupertino_ui`.
///
/// **Use this, not `AppLocalizations.localizationsDelegates`.** That list is
/// generated by `gen-l10n` and still names `flutter_localizations`' Material
/// delegate, which `material_ui` widgets do not read. A French app built from
/// it has no Material strings in French, and Flutter says so with "locale fr
/// is not supported by all of its localization delegates".
const appLocalizationsDelegates = <LocalizationsDelegate<dynamic>>[
  AppLocalizations.delegate,
  ...GlobalMaterialLocalizations.delegates,
];
